381	// ---------- DNS management ----------
382	
383	const RECORD_TYPES = ["A", "AAAA", "CNAME", "TXT", "MX", "NS", "SRV", "ALIAS"] as const;
384	
385	async function ownedDomain(domainId: string) {
386	  const user = await requireUser();
387	  const domain = await db.domain.findUnique({ where: { id: domainId } });
388	  if (!domain || (domain.userId !== user.id && user.role !== "ADMIN")) throw new Error("Forbidden");
389	  if (domain.status !== "ACTIVE") throw new Error("Domain is not active");
390	  return { user, domain };
391	}
392	
393	export async function addDnsRecord(prev: any, formData: FormData): Promise<{ error?: string }> {
394	  const domainId = String(formData.get("domainId") ?? "");
395	  let ctx;
396	  try {
397	    ctx = await ownedDomain(domainId);
398	  } catch (e: any) {
399	    return { error: e.message };
400	  }
401	  const parsed = z
402	    .object({
403	      name: z.string().max(120).default(""),
404	      type: z.enum(RECORD_TYPES),
405	      address: z.string().min(1).max(500),
406	      ttl: z.coerce.number().int().min(60).max(86400).default(300),
407	      mxPref: z.coerce.number().int().min(0).max(65535).optional(),
408	    })
409	    .safeParse({
410	      name: formData.get("name") ?? "",
411	      type: formData.get("type"),
412	      address: formData.get("address"),
413	      ttl: formData.get("ttl") || 300,
414	      mxPref: formData.get("mxPref") || undefined,
415	    });
416	  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid record." };
417	
418	  // "@" or blank => apex (name.com uses empty host for apex)
419	  const host = ["@", ""].includes(parsed.data.name.trim()) ? "" : parsed.data.name.trim();
420	  try {
421	    await addRecord(ctx.domain.name, {
422	      host,
423	      type: parsed.data.type,
424	      answer: parsed.data.address,
425	      ttl: parsed.data.ttl,
426	      priority: parsed.data.type === "MX" || parsed.data.type === "SRV" ? parsed.data.mxPref ?? 10 : undefined,
427	    });
428	  } catch (e: any) {
429	    return { error: String(e?.message ?? e).slice(0, 200) };
430	  }
431	  revalidatePath(`/dashboard/domains/${domainId}`);
432	  return {};
433	}
434	
435	export async function deleteDnsRecord(
436	  domainId: string,
437	  record: { name: string; type: string; address: string }
438	): Promise<{ error?: string }> {
439	  let ctx;
440	  try {
441	    ctx = await ownedDomain(domainId);
442	  } catch (e: any) {
443	    return { error: e.message };
444	  }
445	  const wantHost = ["@", ""].includes(record.name) ? "" : record.name;
446	  try {
447	    const recs = await listRecords(ctx.domain.name);
448	    const match = recs.find((r) => r.host === wantHost && r.type === record.type && r.answer === record.address);
449	    if (!match) return { error: "Record not found (it may have already been removed)." };
450	    await deleteRecord(ctx.domain.name, match.id);
451	  } catch (e: any) {
452	    return { error: String(e?.message ?? e).slice(0, 200) };
453	  }
454	  revalidatePath(`/dashboard/domains/${domainId}`);
455	  return {};
456	}
457	
458	/** One-click: point apex + www at the platform's public IP. */
459	export async function pointDomainAtServer(domainId: string): Promise<{ error?: string }> {
460	  let ctx;
461	  try {
462	    ctx = await ownedDomain(domainId);
463	  } catch (e: any) {
464	    return { error: e.message };
465	  }
466	  const ip = process.env.PUBLIC_IP;
467	  if (!ip) return { error: "Public IP not configured." };
468	  try {
469	    const recs = await listRecords(ctx.domain.name);
470	    for (const r of recs) {
471	      if (["", "www"].includes(r.host) && r.type === "A") await deleteRecord(ctx.domain.name, r.id);
472	    }
473	    await addRecord(ctx.domain.name, { host: "", type: "A", answer: ip, ttl: 300 });
474	    await addRecord(ctx.domain.name, { host: "www", type: "A", answer: ip, ttl: 300 });
475	  } catch (e: any) {
476	    return { error: String(e?.message ?? e).slice(0, 200) };
477	  }
478	  revalidatePath(`/dashboard/domains/${domainId}`);
479	  return {};
480	}
