import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import { connectionTarget, serverRootPassword, type SftpServer } from "../lib/sftp";
import { Client as SshClient } from "ssh2";
import type { Job, SslCertificate } from "@prisma/client";

/**
 * SSL certificate issuance handler (SSL_ISSUE).
 *
 * `worker/index.ts` owns the job loop and the `handlers` map; wire this in there:
 *   SSL_ISSUE: sslIssue,
 *
 * Ownership + domain validation are enforced at enqueue time
 * (lib/actions-ssl.ts), so this handler trusts `payload.certId`.
 *
 * SAFETY: actually issuing a Let's Encrypt cert means SSHing to the customer's
 * VM and running certbot against a live, DNS-pointed domain. That is a real,
 * side-effecting operation, so it is DISABLED by default. The real path only
 * runs when we're NOT in SANDBOX and ENABLE_REAL_SSL === "1"; otherwise this
 * handler always takes the simulated-success branch (which is also what
 * SANDBOX/staging requires) and no SSH is ever opened.
 */

/** A Let's Encrypt certificate is valid for 90 days. */
const CERT_LIFETIME_MS = 90 * 86400_000;

/**
 * ACME account / contact email passed to certbot (`-m`). Let's Encrypt uses it
 * for expiry warnings. Override with CERTBOT_EMAIL; falls back to a constant.
 */
const CERTBOT_EMAIL = process.env.CERTBOT_EMAIL || "ssl-admin@nxeon.local";

/** Overall SSH connect timeout, and per-certbot-command timeout. */
const SSH_CONNECT_TIMEOUT_MS = 15_000;
const CERTBOT_TIMEOUT_MS = 120_000;
/** Shorter budget for the quick pre-flight/install probes. */
const PROBE_TIMEOUT_MS = 60_000;

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[ssl] notify failed", e);
  }
}

// ----------------------------------------------------------------------------
// Real issuance path (SSH + certbot). Only reachable when
// `!SANDBOX && ENABLE_REAL_SSL === "1"` — see the guard in sslIssue().
// ----------------------------------------------------------------------------

type SshResult = { code: number | null; stdout: string; stderr: string };

/**
 * Single-quote a value for safe interpolation into a POSIX shell command.
 * We already restrict the domain to a strict charset below, but everything that
 * reaches a remote shell is quoted defensively regardless.
 */
function shellQuote(s: string): string {
  return `'${s.replace(/'/g, `'\\''`)}'`;
}

/** Domains must look like real hostnames before we hand them to certbot. */
function assertSafeDomain(domain: string): void {
  if (!/^(?=.{1,253}$)([a-zA-Z0-9-]{1,63}\.)+[a-zA-Z]{2,63}$/.test(domain)) {
    throw new Error(`Refusing to issue for an unexpected domain: ${domain}`);
  }
}

/**
 * Run one command on an already-connected ssh2 client, capturing stdout/stderr
 * and the exit code. Rejects on transport error or if the command exceeds
 * `timeoutMs` (the channel is torn down so a hung certbot can't wedge the worker).
 */
function sshExec(conn: SshClient, command: string, timeoutMs: number): Promise<SshResult> {
  return new Promise((resolve, reject) => {
    conn.exec(command, (err, stream) => {
      if (err) return reject(err);
      let stdout = "";
      let stderr = "";
      let settled = false;
      const timer = setTimeout(() => {
        if (settled) return;
        settled = true;
        try {
          stream.close();
        } catch {
          /* best effort */
        }
        reject(new Error(`Command timed out after ${Math.round(timeoutMs / 1000)}s`));
      }, timeoutMs);

      stream
        .on("close", (code: number | null) => {
          if (settled) return;
          settled = true;
          clearTimeout(timer);
          resolve({ code, stdout, stderr });
        })
        .on("data", (d: Buffer) => {
          stdout += d.toString("utf8");
        })
        .stderr.on("data", (d: Buffer) => {
          stderr += d.toString("utf8");
        });
    });
  });
}

/** Open an ssh2 connection to a server, run `fn`, and always end the connection. */
async function withSsh<T>(
  target: { host: string; port: number },
  password: string,
  fn: (conn: SshClient) => Promise<T>
): Promise<T> {
  const conn = new SshClient();
  await new Promise<void>((resolve, reject) => {
    const timer = setTimeout(() => {
      try {
        conn.end();
      } catch {
        /* best effort */
      }
      reject(new Error(`SSH connect timed out after ${Math.round(SSH_CONNECT_TIMEOUT_MS / 1000)}s`));
    }, SSH_CONNECT_TIMEOUT_MS);
    conn
      .on("ready", () => {
        clearTimeout(timer);
        resolve();
      })
      .on("error", (e) => {
        clearTimeout(timer);
        reject(e);
      })
      .connect({
        host: target.host,
        port: target.port,
        username: "root",
        password,
        readyTimeout: SSH_CONNECT_TIMEOUT_MS,
      });
  });
  try {
    return await fn(conn);
  } finally {
    try {
      conn.end();
    } catch {
      /* best effort */
    }
  }
}

/**
 * Really issue a Let's Encrypt certificate for `cert.domain` by SSHing into the
 * customer's own VM (same host/port/root-password derivation as lib/sftp) and
 * driving certbot in --standalone mode. Throws on any failure so the caller's
 * catch marks the cert FAILED with the reason.
 *
 * Steps on the customer VM:
 *   1. Detect the package manager (apt-get / dnf) and ensure `certbot` exists,
 *      installing it if missing.
 *   2. Confirm TCP port 80 is free (standalone binds it for the HTTP-01
 *      challenge) — surface a clear error otherwise.
 *   3. certbot certonly --standalone -n --agree-tos -m <email> -d <domain>.
 *   4. Read the real notAfter from the issued fullchain via `openssl x509
 *      -enddate`, falling back to now+90d if that can't be parsed.
 *
 * Returns the issuedAt/expiresAt to persist.
 */
async function issueRealCertificate(
  cert: SslCertificate
): Promise<{ issuedAt: Date; expiresAt: Date }> {
  const domain = cert.domain;
  assertSafeDomain(domain);

  if (!cert.serverId) {
    throw new Error("Certificate is not attached to a server.");
  }

  // Load exactly the fields connectionTarget()/SSH need (mirrors lib/sftp usage).
  const server = await db.server.findUnique({
    where: { id: cert.serverId },
    select: {
      id: true,
      rootPassword: true,
      rootPasswordEnc: true,
      sshPort: true,
      dedicatedIp: { select: { address: true } },
    },
  });
  if (!server) throw new Error(`Server ${cert.serverId} not found.`);

  const target = connectionTarget(server as SftpServer);
  if (!target) {
    throw new Error("Server is not reachable yet — connection details are pending.");
  }
  const rootPassword = serverRootPassword(server);
  if (!rootPassword) throw new Error("Server has no root password set.");

  const qDomain = shellQuote(domain);
  const qEmail = shellQuote(CERTBOT_EMAIL);

  return withSsh(target, rootPassword, async (conn) => {
    // 1. Ensure certbot is present. `command -v` is portable; install only if missing.
    const have = await sshExec(conn, "command -v certbot >/dev/null 2>&1 && echo yes || echo no", PROBE_TIMEOUT_MS);
    if (have.stdout.trim() !== "yes") {
      // Pick the installer from whichever package manager exists.
      const pm = await sshExec(
        conn,
        "if command -v apt-get >/dev/null 2>&1; then echo apt; " +
          "elif command -v dnf >/dev/null 2>&1; then echo dnf; else echo none; fi",
        PROBE_TIMEOUT_MS
      );
      const which = pm.stdout.trim();
      let installCmd: string;
      if (which === "apt") {
        installCmd = "DEBIAN_FRONTEND=noninteractive apt-get update -y && apt-get install -y certbot";
      } else if (which === "dnf") {
        installCmd = "dnf install -y certbot";
      } else {
        throw new Error("No supported package manager (apt-get/dnf) found to install certbot.");
      }
      const inst = await sshExec(conn, installCmd, CERTBOT_TIMEOUT_MS);
      if (inst.code !== 0) {
        throw new Error(`certbot install failed: ${(inst.stderr || inst.stdout).trim().slice(0, 300)}`);
      }
      // Re-check that certbot is now on PATH.
      const recheck = await sshExec(conn, "command -v certbot >/dev/null 2>&1 && echo yes || echo no", PROBE_TIMEOUT_MS);
      if (recheck.stdout.trim() !== "yes") {
        throw new Error("certbot still not available after install.");
      }
    }

    // 2. Standalone needs port 80. If something is already listening, bail with a
    //    clear message rather than letting certbot fail cryptically. (We default to
    //    --standalone; --webroot would only be used if a docroot were known.)
    const portCheck = await sshExec(
      conn,
      "ss -ltnH 'sport = :80' 2>/dev/null | head -n1 || true",
      PROBE_TIMEOUT_MS
    );
    if (portCheck.stdout.trim().length > 0) {
      throw new Error(
        "Port 80 is in use by another service; free it (or configure webroot issuance) before requesting a standalone certificate."
      );
    }

    // 3. Issue. --standalone spins up certbot's own HTTP-01 responder on :80.
    const certbotCmd =
      `certbot certonly --standalone -n --agree-tos -m ${qEmail} -d ${qDomain}`;
    const run = await sshExec(conn, certbotCmd, CERTBOT_TIMEOUT_MS);
    const combined = `${run.stdout}\n${run.stderr}`;
    // certbot exits 0 on success (including "Certificate not yet due for renewal").
    const succeeded =
      run.code === 0 &&
      /Congratulations|Successfully received certificate|not yet due for renewal|Certificate is saved/i.test(combined);
    if (!succeeded) {
      throw new Error(`certbot failed: ${combined.trim().slice(0, 400)}`);
    }

    // 4. Prefer the real notAfter from the issued chain; fall back to now+90d.
    const now = new Date();
    let expiresAt = new Date(now.getTime() + CERT_LIFETIME_MS);
    const live = `/etc/letsencrypt/live/${domain}/fullchain.pem`;
    const enddate = await sshExec(
      conn,
      `openssl x509 -enddate -noout -in ${shellQuote(live)} 2>/dev/null || true`,
      PROBE_TIMEOUT_MS
    );
    const m = enddate.stdout.match(/notAfter=(.+)/);
    if (m) {
      const parsed = new Date(m[1].trim());
      if (!Number.isNaN(parsed.getTime())) expiresAt = parsed;
    }

    return { issuedAt: now, expiresAt };
  });
}

export async function sslIssue(job: Job): Promise<void> {
  const payload = (job.payload ?? {}) as { certId?: string };
  if (!payload.certId) throw new Error("ssl job: missing certId");

  const cert = await db.sslCertificate.findUnique({ where: { id: payload.certId } });
  if (!cert) throw new Error(`SslCertificate ${payload.certId} not found`);

  // Mark in-flight so the UI shows "issuing" while we work.
  await db.sslCertificate.update({ where: { id: cert.id }, data: { status: "ISSUING" } });

  try {
    // ---------------------------------------------------------------------
    // Real issuance path (SSH + certbot). Guarded so it can never run by
    // accident: it happens ONLY when ENABLE_REAL_SSL is explicitly set AND we
    // are not in SANDBOX. In every other case we fall through to the simulated
    // success below (the default, and what SANDBOX/staging requires).
    //
    // The real path (issueRealCertificate) SSHes into the customer's own VM —
    // host/port/root/password derived exactly like lib/sftp — and runs:
    //   certbot certonly --standalone -n --agree-tos -m <email> -d <domain>
    // installing certbot first if needed and reading the real notAfter back.
    // ---------------------------------------------------------------------
    const realIssuanceEnabled = !SANDBOX && process.env.ENABLE_REAL_SSL === "1";
    if (realIssuanceEnabled) {
      const { issuedAt, expiresAt } = await issueRealCertificate(cert);
      await db.sslCertificate.update({
        where: { id: cert.id },
        data: { status: "ACTIVE", issuedAt, expiresAt, lastError: null },
      });
      await notify(
        cert.userId,
        `SSL certificate issued for ${cert.domain}`,
        "Your Let's Encrypt certificate is active.",
        "/dashboard/ssl"
      );
      return;
    }

    // Default: simulated success (SANDBOX-safe, no SSH, no certbot).
    const now = new Date();
    await db.sslCertificate.update({
      where: { id: cert.id },
      data: {
        status: "ACTIVE",
        issuedAt: now,
        expiresAt: new Date(now.getTime() + CERT_LIFETIME_MS),
        lastError: null,
      },
    });
    await notify(
      cert.userId,
      `SSL certificate issued for ${cert.domain}`,
      "Your Let's Encrypt certificate is active and valid for 90 days (sandbox).",
      "/dashboard/ssl"
    );
  } catch (e: any) {
    const reason = String(e?.message ?? e).slice(0, 500);
    await db.sslCertificate.update({
      where: { id: cert.id },
      data: { status: "FAILED", lastError: reason },
    });
    await notify(
      cert.userId,
      `SSL certificate failed for ${cert.domain}`,
      reason.slice(0, 200),
      "/dashboard/ssl"
    );
  }
}

