238	/**
239	 * Poll every TRANSFER_PENDING domain and move it to its real state.
240	 *
241	 * An ICANN transfer takes ~5-7 days and only completes once the owner approves
242	 * an email from the LOSING registrar, so this is a slow poll, not a spinner:
243	 *   completed -> ACTIVE, dates taken from the registrar, auth code scrubbed
244	 *   failed    -> TRANSFER_FAILED, wallet credited back, reason recorded
245	 *   pending   -> raw registrar status refreshed for display, gentle nudge
246	 *
247	 * Every mutation goes through the shared CAS-guarded settle helpers, so a
248	 * re-run, two workers racing, or a customer cancelling at the same moment can
249	 * never credit the same transfer twice.
250	 */
251	async function domainTransferInSweep(now: Date) {
252	  if (!transfersAvailable()) return; // registrar not configured — skip silently
253	
254	  const pending = await db.domain.findMany({
255	    where: { status: "TRANSFER_PENDING", isTransferIn: true },
256	  });
257	
258	  for (const domain of pending) {
259	    try {
260	      const info = await getTransfer(domain.name, domain.transferStartedAt);
261	
262	      // No transfer on record. Normal once a transfer settles and drops off the
263	      // registrar's list — resolve it against the account rather than guessing.
264	      if (!info) {
265	        const owned = await domainInfo(domain.name).catch(() => null);
266	        if (owned?.expires) {
267	          await completeTransferIn(domain, "completed", owned);
268	          continue;
269	        }
270	        const startedAt = domain.transferStartedAt ?? domain.createdAt;
271	        const ageDays = (now.getTime() - startedAt.getTime()) / DAY;
272	        if (ageDays > TRANSFER_STALE_DAYS) {
273	          await failTransferIn(
274	            domain,
275	            null,
276	            `The registrar has no record of this transfer after ${Math.round(ageDays)} days. It did not complete.`
277	          );
278	        }
279	        continue;
280	      }
281	
282	      const outcome = transferOutcome(info.status);
283	
284	      if (outcome === "completed") {
285	        const owned = await domainInfo(domain.name).catch(() => null);
286	        await completeTransferIn(domain, info.status, owned);
287	        continue;
288	      }
289	
290	      if (outcome === "failed") {
291	        await failTransferIn(domain, info.status, transferStatusLabel(info.status));
292	        continue;
293	      }
294	
295	      // Still in flight — keep the displayed registrar status fresh.
296	      if (info.status !== domain.transferStatus || (info.email && info.email !== domain.transferEmail)) {
297	        await db.domain.update({
298	          where: { id: domain.id },
299	          data: { transferStatus: info.status, ...(info.email ? { transferEmail: info.email } : {}) },
300	        });
301	      }
302	      await nudgeTransferApproval(domain, info.status, info.email, now);
303	    } catch (e) {
304	      // One unhappy domain must never abort the sweep. Nothing is settled and
305	      // no money moves on an unknown state — we simply try again next pass.
306	      console.error(`[billing] transfer-in poll failed for ${domain.name}`, e);
307	    }
308	  }
309	}
