107	function CertActions({ cert }: { cert: CertRow }) {
108	  const [error, setError] = useState<string | null>(null);
109	  const [pending, start] = useTransition();
110	
111	  const run = (fn: () => Promise<{ error?: string }>, confirmMsg?: string) => {
112	    if (confirmMsg && !window.confirm(confirmMsg)) return;
113	    start(async () => {
114	      setError(null);
115	      const res = await fn();
