131	          className={`relative inline-flex h-6 w-11 shrink-0 items-center rounded-full transition-colors ${
132	            cert.autoRenew ? "bg-brand-500" : "bg-white/15"
133	          } ${pending ? "opacity-60" : ""}`}
134	        >
135	          <span
136	            className={`inline-block h-5 w-5 transform rounded-full bg-white shadow transition-transform ${
137	              cert.autoRenew ? "translate-x-5" : "translate-x-0.5"
138	            }`}
139	          />
140	        </button>
141	        <button
142	          className="btn-danger px-3 py-1 text-xs"
143	          disabled={pending || cert.status === "ISSUING"}
144	          onClick={() =>
145	            run(
146	              () => deleteCertificate(cert.id),
147	              `Delete the certificate for "${cert.domain}"? This removes it from your account.`
148	            )
149	          }
150	        >
151	          Delete
152	        </button>
153	      </div>
154	    </div>
155	  );
156	}
