/* -------------------------------------------------------------------------- *
 * Import / Export / Reset — extra DNS tools mounted alongside quick setup.
 * -------------------------------------------------------------------------- */

export function DnsImportExportReset({
  domainId,
  publicIp,
}: {
  domainId: string;
  publicIp: string;
}) {
  const [text, setText] = useState("");
  const [importResult, setImportResult] = useState<BulkResult | null>(null);
  const [resetResult, setResetResult] = useState<BulkResult | null>(null);
  const [importing, startImport] = useTransition();
  const [resetting, startReset] = useTransition();

  function runImport() {
    startImport(async () => {
      setImportResult(null);
      const res = await importDnsRecords(domainId, text);
      setImportResult(res);
      if (!res.error) setText("");
    });
  }

  function runReset() {
    const phrase = window.prompt(
      "This removes ALL A/AAAA/CNAME/TXT/MX/SRV records and restores a default set" +
        (publicIp ? ` pointing at ${publicIp}` : "") +
        ".\n\nType RESET to confirm."
    );
    if (phrase !== "RESET") return;
    startReset(async () => {
      setResetResult(null);
      const res = await resetDnsToDefaults(domainId);
      setResetResult(res);
    });
  }

  return (
    <div className="card">
      <div className="mb-1 flex items-center justify-between">
        <h2 className="font-semibold">Import / export &amp; reset</h2>
        <Badge tone="slate">bulk tools</Badge>
      </div>
      <p className="mb-4 text-sm text-slate-400">
        Move DNS between providers, or start over. Export downloads a CSV you can re-import here.
      </p>

      <div className="mb-4 flex flex-wrap gap-2">
        <a className="btn-secondary" href={`/api/domains/${domainId}/dns-export`} target="_blank" rel="noreferrer">
          Export records (CSV)
        </a>
        <button className="btn-danger" disabled={resetting} onClick={runReset}>
          {resetting ? "Resetting…" : "Reset DNS to defaults"}
        </button>
      </div>
      {resetResult && <ResultBox result={resetResult} />}

      <div className="mt-4">
        <label className="label">Import records</label>
        <textarea
          className="input min-h-[120px] font-mono text-xs"
          placeholder={"name,type,value,ttl,priority\n@,A,203.0.113.10,300,\nwww,CNAME,example.com.,300,\n@,MX,aspmx.l.google.com.,3600,1"}
          value={text}
          onChange={(e) => setText(e.target.value)}
          spellCheck={false}
        />
        <p className="mt-1.5 text-xs text-slate-500">
          One record per line: <span className="font-mono">name,type,value,ttl,priority</span> (comma or space
          separated). Lines starting with <span className="font-mono">#</span> are ignored. Records that already
          exist are skipped.
        </p>
        <div className="mt-3 flex justify-end">
          <button className="btn-primary" disabled={importing || !text.trim()} onClick={runImport}>
            {importing ? "Importing…" : "Import records"}
          </button>
        </div>
        {importResult && <ResultBox result={importResult} />}
      </div>
    </div>
  );
}

