"use client";

import { useState, useTransition } from "react";
import { applyCouponToTopup } from "@/lib/actions-growth";
import type { CouponApplyResult } from "@/lib/growth";

const COUPON_COOKIE = "nxeon_coupon";
// Nominal amount used only to validate the code before the user picks an amount.
const PREVIEW_CENTS = 2500;

function setCookie(code: string) {
  document.cookie = `${COUPON_COOKIE}=${encodeURIComponent(code)}; path=/; max-age=${60 * 60}; SameSite=Lax`;
}
function clearCookie() {
  document.cookie = `${COUPON_COOKIE}=; path=/; max-age=0; SameSite=Lax`;
}

/**
 * Promo-code entry for the wallet top-up flow. On a valid code it stores the
 * code in a short-lived cookie which `topUp` reads and applies to the real
 * top-up amount (this keeps the existing AddFunds form untouched).
 */
export function CouponField() {
  const [code, setCode] = useState("");
  const [applied, setApplied] = useState<{ code: string; label: string } | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  const apply = () => {
    setError(null);
    const trimmed = code.trim();
    if (!trimmed) {
      setError("Enter a promo code.");
      return;
    }
    start(async () => {
      const res: CouponApplyResult = await applyCouponToTopup(trimmed, PREVIEW_CENTS);
      if (res.ok) {
        setCookie(res.code);
        setApplied({ code: res.code, label: res.label });
        setError(null);
      } else {
        clearCookie();
        setApplied(null);
        setError(res.error);
      }
    });
  };

  const remove = () => {
    clearCookie();
    setApplied(null);
    setCode("");
    setError(null);
  };

  if (applied) {
    return (
      <div className="flex flex-wrap items-center gap-3 rounded-lg border border-emerald-500/30 bg-emerald-500/[0.06] px-3 py-2 text-sm">
        <span className="font-medium text-emerald-300">
          Code <span className="font-mono">{applied.code}</span> applied — {applied.label}
        </span>
        <span className="text-xs text-slate-400">Bonus is credited when you add funds.</span>
        <button type="button" onClick={remove} className="btn-ghost ml-auto py-1 text-xs">
          Remove
        </button>
      </div>
    );
  }

  return (
    <div>
      <label className="label">Promo code</label>
      <div className="flex items-center gap-2">
        <input
          className="input w-48 uppercase"
          value={code}
          onChange={(e) => setCode(e.target.value)}
          placeholder="WELCOME10"
          maxLength={32}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              e.preventDefault();
              apply();
            }
          }}
        />
        <button type="button" className="btn-secondary py-2" onClick={apply} disabled={pending}>
          {pending ? "Checking…" : "Apply"}
        </button>
      </div>
      {error && <p className="mt-2 text-sm text-red-400">{error}</p>}
    </div>
  );
}

