16	/** Local sentinel: requested payout exceeds the caller's cashable affiliate balance. */
17	class PayoutExceedsAvailableError extends Error {
18	  availableCents: number;
19	  constructor(availableCents: number) {
20	    super("PAYOUT_EXCEEDS_AVAILABLE");
21	    this.name = "PayoutExceedsAvailableError";
22	    this.availableCents = availableCents;
23	  }
24	}
