26	// ---------- Customer: request a payout ----------
27	
28	/**
29	 * Request an affiliate payout for `amountCents`. Model: referral rewards already
30	 * live in the wallet, so a payout CONVERTS wallet credit into a cash-out request —
31	 * it DEBITS the wallet now and records a PENDING AffiliatePayout (admin later marks
32	 * PAID; a DECLINE credits the wallet back). Guards:
33	 *  - integer cents ≥ MIN_PAYOUT_CENTS ($25)
34	 *  - amount ≤ the caller's cashable affiliate balance (unclaimed referral
35	 *    commission, capped by the actual wallet balance), re-read INSIDE the
36	 *    transaction so two concurrent requests can't both pass a stale check.
37	 *  - the wallet debit is an atomic guarded updateMany, so even a race can never
38	 *    drive the balance negative — the second request fails cleanly.
39	 */
40	export async function requestAffiliatePayout(
41	  amountCents: number
42	): Promise<{ ok?: boolean; error?: string }> {
43	  const user = await requireUser();
44	
45	  // Feature flag: the referral/affiliate program can be switched off platform-wide.
46	  if (!(await getSettingBool("feature_referrals", true))) {
47	    return { error: "The affiliate program is currently unavailable." };
48	  }
49	
50	  const cents = Math.round(Number(amountCents));
51	  if (!Number.isFinite(cents) || cents <= 0) {
52	    return { error: "Enter a valid amount." };
53	  }
54	  if (cents < MIN_PAYOUT_CENTS) {
55	    return { error: `Minimum payout is $${(MIN_PAYOUT_CENTS / 100).toFixed(2)}.` };
56	  }
57	
58	  try {
59	    await db.$transaction(async (tx) => {
60	      // Re-read all state inside the tx to serialize concurrent requests.
61	      const [account, earnedAgg, payouts] = await Promise.all([
62	        tx.user.findUnique({ where: { id: user.id }, select: { balanceCents: true } }),
63	        tx.walletTransaction.aggregate({
64	          _sum: { amountCents: true },
65	          where: { userId: user.id, description: REFERRAL_EARNING_DESCRIPTION },
66	        }),
67	        tx.affiliatePayout.findMany({
68	          where: { userId: user.id, status: { not: "DECLINED" } },
69	          select: { amountCents: true },
70	        }),
71	      ]);
72	      const walletBalanceCents = account?.balanceCents ?? 0;
73	      const totalEarnedCents = earnedAgg._sum.amountCents ?? 0;
74	      const claimedCents = payouts.reduce((s, p) => s + p.amountCents, 0);
75	      const availableCents = Math.max(
76	        0,
77	        Math.min(walletBalanceCents, totalEarnedCents - claimedCents)
78	      );
79	      if (cents > availableCents) throw new PayoutExceedsAvailableError(availableCents);
80	
81	      // Atomic guarded debit — hard-stops any residual race from overdrawing.
82	      await debitWallet(tx, user.id, cents);
83	      await tx.walletTransaction.create({
84	        data: {
85	          userId: user.id,
86	          amountCents: -cents,
87	          description: "Affiliate payout request (wallet cash-out)",
88	        },
89	      });
90	      await tx.affiliatePayout.create({
91	        data: { userId: user.id, amountCents: cents, status: "PENDING" },
92	      });
93	      await tx.auditLog.create({
94	        data: {
95	          userId: user.id,
96	          action: "affiliate.payout_request",
97	          detail: `$${(cents / 100).toFixed(2)}`,
98	        },
99	      });
100	    });
101	  } catch (e) {
102	    if (e instanceof PayoutExceedsAvailableError) {
103	      return { error: `You only have $${(e.availableCents / 100).toFixed(2)} available to withdraw.` };
104	    }
105	    if (e instanceof InsufficientBalanceError) {
106	      return { error: "Insufficient wallet balance for this payout." };
107	    }
108	    throw e;
109	  }
110	
111	  revalidatePath("/dashboard/affiliate");
112	  return { ok: true };
113	}
114	
115	// ---------- Admin: update a payout's status ----------
116	
117	const ALLOWED: readonly PayoutStatus[] = PAYOUT_STATUSES;
118	
119	/**
120	 * Move a payout request to APPROVED / PAID / DECLINED. Money already left the
121	 * wallet when the request was created, so:
122	 *   - PAID     : just stamp `paidAt` (no wallet change — cash was already reserved).
123	 *   - DECLINED : credit the reserved amount back to the wallet (cash-out cancelled).
124	 *   - reactivating a DECLINED payout (back to PENDING/APPROVED/PAID): re-debit it,
125	 *     guarded, so a declined-then-reinstated payout can't be double-spent.
126	 * Billing-area gated. The status change + wallet move are one transaction.
127	 */
128	export async function adminUpdatePayout(
129	  id: string,
130	  status: string
131	): Promise<{ ok?: boolean; error?: string }> {
132	  const admin = await requireArea("billing");
133	
134	  if (!ALLOWED.includes(status as PayoutStatus)) {
135	    return { error: "Invalid status." };
136	  }
137	  const payout = await db.affiliatePayout.findUnique({ where: { id } });
138	  if (!payout) return { error: "Payout not found." };
139	
140	  const wasDeclined = payout.status === "DECLINED";
141	  const willDecline = status === "DECLINED";
142	
143	  try {
144	    await db.$transaction(async (tx) => {
145	      await tx.affiliatePayout.update({
146	        where: { id },
147	        data: {
148	          status,
149	          paidAt: status === "PAID" ? new Date() : null,
150	        },
151	      });
152	      if (willDecline && !wasDeclined) {
153	        // Cancel the cash-out: return the reserved funds to the wallet.
154	        await tx.user.update({
155	          where: { id: payout.userId },
156	          data: { balanceCents: { increment: payout.amountCents } },
157	        });
