164	        });
165	      } else if (!willDecline && wasDeclined) {
166	        // Reinstating a previously-declined payout: re-reserve the funds (guarded).
167	        await debitWallet(tx, payout.userId, payout.amountCents);
168	        await tx.walletTransaction.create({
169	          data: {
170	            userId: payout.userId,
171	            amountCents: -payout.amountCents,
172	            description: "Affiliate payout reinstated (wallet cash-out)",
173	          },
174	        });
175	      }
176	    });
