56	/**
57	 * Validate a promo code for the CURRENT user against a top-up of `baseCents` and
58	 * return the bonus that would be credited. Read-only: it never mutates state,
59	 * so it is safe to call both for the live preview (CouponField) and again inside
60	 * `topUp` to compute the real bonus. Enforces active / expiry / scope /
61	 * minAmount / maxRedemptions / firstTimeOnly / one-per-user rules.
62	 */
63	export async function applyCouponToTopup(
64	  code: string,
65	  baseCents: number
66	): Promise<CouponApplyResult> {
67	  const user = await requireUser();
68	  // Global kill-switch: when coupons are disabled no code may be redeemed.
69	  // Checked here so both the live preview and the real `topUp` apply are covered.
70	  if (!(await getSettingBool("coupons_enabled", true))) {
71	    return { ok: false, error: "Promo codes are currently disabled." };
72	  }
73	  const normalized = String(code ?? "").trim().toUpperCase();
74	  if (!normalized) return { ok: false, error: "Enter a promo code." };
75	
76	  const coupon = await db.coupon.findUnique({ where: { code: normalized } });
77	  if (!coupon || !coupon.active) return { ok: false, error: "That code isn’t valid." };
78	  if (coupon.scope === "ORDER") {
79	    return { ok: false, error: "This code only applies to server orders." };
80	  }
81	  if (coupon.expiresAt && coupon.expiresAt.getTime() < Date.now()) {
82	    return { ok: false, error: "This code has expired." };
83	  }
84	  if (coupon.maxRedemptions !== null && coupon.timesRedeemed >= coupon.maxRedemptions) {
85	    return { ok: false, error: "This code has reached its redemption limit." };
86	  }
87	  if (coupon.minAmountCents !== null && baseCents < coupon.minAmountCents) {
88	    return {
89	      ok: false,
90	      error: `Add at least $${(coupon.minAmountCents / 100).toFixed(2)} to use this code.`,
91	    };
92	  }
93	
94	  // One redemption per user (mirrors the @@unique([couponId,userId]) constraint).
95	  const already = await db.couponRedemption.findUnique({
96	    where: { couponId_userId: { couponId: coupon.id, userId: user.id } },
97	  });
98	  if (already) return { ok: false, error: "You’ve already used this code." };
99	
100	  if (coupon.firstTimeOnly) {
101	    // "First-time" = the user has never received a positive wallet credit before.
102	    const priorCredits = await db.walletTransaction.count({
103	      where: { userId: user.id, amountCents: { gt: 0 } },
104	    });
105	    if (priorCredits > 0) {
106	      return { ok: false, error: "This code is for first-time customers only." };
107	    }
108	  }
109	
110	  const bonusCents = Math.max(0, couponBonusForTopup(coupon, baseCents));
111	  return {
112	    ok: true,
113	    couponId: coupon.id,
114	    code: coupon.code,
115	    bonusCents,
116	    label: describeCoupon(coupon),
117	  };
118	}
