225	/**
226	 * Grant the configured signup free credit to a freshly-registered user, once.
227	 * No-op when SIGNUP_FREE_CREDIT_CENTS is 0 or the user already has signup credit.
228	 * Callable from `register` in lib/actions.ts.
229	 */
230	export async function grantSignupCredit(userId: string): Promise<number> {
231	  await assertInternalGrowthCaller(userId);
232	  // Prefer the admin-editable setting (`signup_free_credit_cents`); fall back to
233	  // the legacy SIGNUP_FREE_CREDIT_CENTS env default when the setting is unset.
234	  const cents = await getSettingInt("signup_free_credit_cents", signupFreeCreditCents());
235	  if (cents <= 0) return 0;
236	  const user = await db.user.findUnique({ where: { id: userId } });
237	  if (!user || user.signupCreditCents > 0) return 0;
238	  await db.$transaction([
239	    db.user.update({
240	      where: { id: userId },
241	      data: { balanceCents: { increment: cents }, signupCreditCents: cents },
242	    }),
243	    db.walletTransaction.create({
244	      data: { userId, amountCents: cents, description: "Welcome credit" },
245	    }),
246	  ]);
247	  return cents;
248	}
