216	    await db.auditLog
217	      .create({
218	        data: {
219	          userId: user.id,
220	          action: "domain.transfer_in.submitted",
221	          detail: `${domain} status=${submitted.status} charge=${totalCents}c`,
222	        },
223	      })
224	      .catch(() => {});
225	
226	    // ---- Charge + row, atomically. ----
227	    let domainId: string;
228	    try {
229	      domainId = await db.$transaction(async (tx) => {
230	        const transferData = {
231	          status: "TRANSFER_PENDING" as const,
232	          isTransferIn: true,
233	          transferAuthCodeEnc: encryptSecret(authCode),
234	          transferStartedAt: new Date(),
235	          transferStatus: submitted.status,
236	          transferEmail: submitted.email,
237	          priceCents: check.priceCents!,
238	          costCents: check.costCents!,
239	          termYears: TRANSFER_TERM_YEARS,
240	          registrar: "name.com",
241	          error: null,
242	        };
243	        // Write the row FIRST: a unique conflict or a lost CAS aborts the whole
244	        // transaction before the wallet is touched.
245	        let id: string;
246	        if (existing) {
247	          const swapped = await tx.domain.updateMany({
248	            where: { id: existing.id, status: existing.status },
249	            data: transferData,
250	          });
251	          if (swapped.count === 0) throw new DuplicateDomainError();
252	          id = existing.id;
253	        } else {
254	          const created = await tx.domain.create({
255	            data: { name: domain, userId: user.id, ...transferData },
256	          });
257	          id = created.id;
258	        }
259	        await debitWallet(tx, user.id, totalCents);
260	        await tx.walletTransaction.create({
261	          data: {
262	            userId: user.id,
263	            amountCents: -totalCents,
264	            description: transferChargeDescription(domain),
265	          },
266	        });
267	        await tx.invoice.create({
268	          data: invoiceCreateData({
269	            userId: user.id,
270	            description: transferChargeDescription(domain),
271	            status: "PAID",
272	            lineItems: [
273	              {
274	                description: `Domain transfer in — ${domain} (adds 1 year to the registration)`,
275	                qty: 1,
276	                unitCents: totalCents,
277	                amountCents: totalCents,
278	              },
279	            ],
280	          }),
281	        });
282	        return id;
283	      });
284	    } catch (e) {
285	      // The transfer IS live at the registrar but we could not bill it. Undo the
286	      // submission rather than do unpaid work; if the registrar won't cancel,
287	      // flag it for ops instead of silently swallowing it.
288	      let cancelled = false;
289	      try {
290	        await cancelTransfer(domain);
291	        cancelled = true;
292	      } catch {
293	        /* registrar refused the cancel — ops has to unwind it manually */
294	      }
295	      await db.auditLog
296	        .create({
297	          data: {
298	            userId: user.id,
299	            action: "domain.transfer_in.uncharged",
300	            detail: `${domain}: submitted but not charged (${errMsg(e)}) — cancelled=${cancelled}`.slice(0, 500),
301	          },
302	        })
303	        .catch(() => {});
304	
305	      if (e instanceof InsufficientBalanceError) {
306	        return {
307	          error: cancelled
308	            ? "Your balance dropped below the transfer price before we could charge it, so we cancelled the transfer at the registrar. Top up and try again — you were not charged."
309	            : "Your balance dropped below the transfer price before we could charge it. We've flagged this for our team — you were not charged. Please contact support before retrying.",
310	        };
311	      }
312	      if (e instanceof DuplicateDomainError || isUniqueConflict(e)) {
313	        return { error: "A transfer for this domain is already in progress — you have not been charged twice." };
314	      }
315	      throw e;
316	    }
317	
318	    await db.notification
319	      .create({
320	        data: {
321	          userId: user.id,
322	          title: `Transfer started: ${domain}`,
323	          body:
324	            `We've submitted the transfer to the registrar. Inbound transfers normally take 5–7 days ` +
325	            `and you must approve a confirmation email from your CURRENT registrar before it can complete.`,
326	          href: `/dashboard/domains/${domainId}`,
327	        },
328	      })
329	      .catch(() => {});
330	
331	    revalidatePath("/dashboard/domains");
332	    redirect(`/dashboard/domains/${domainId}`);
333	  } finally {
334	    endTransferSubmit(guardKey);
335	  }
336	}
337	
338	/* ------------------------------------------------------------------ *
339	 * Cancel an in-flight transfer
340	 * ------------------------------------------------------------------ */
341	
342	/**
343	 * Cancel an inbound transfer at the registrar and credit the customer back.
344	 *
345	 * The credit happens ONLY after the registrar confirms the cancellation — we do
346	 * not assume a refund we haven't been given. If the registrar refuses (the most
347	 * common reason being that the transfer already completed at the registry) we
348	 * say so and move no money.
349	 */
350	export async function cancelTransferIn(
351	  domainId: string
352	): Promise<{ error?: string; note?: string }> {
353	  const user = await requireUser();
354	  // Credits the wallet — same guard as every other money-moving action.
355	  await assertNotImpersonating();
356	
357	  const domain = await db.domain.findUnique({ where: { id: domainId } });
358	  if (!domain || (domain.userId !== user.id && user.role !== "ADMIN")) return { error: "Not found." };
359	  if (!domain.isTransferIn || domain.status !== "TRANSFER_PENDING") {
360	    return { error: "There's no transfer in progress for this domain." };
361	  }
362	
363	  const rl = checkRateLimit(`domain-transfer-cancel:${user.id}`, { max: 6, windowMs: 10 * 60_000 });
364	  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };
365	
366	  const guardKey = `transfer-cancel:${domain.userId}:${domain.name}`;
367	  if (!beginTransferSubmit(guardKey)) return { error: "That cancellation is already being processed." };
368	
369	  try {
370	    try {
371	      await cancelTransfer(domain.name);
372	    } catch (e) {
373	      return {
374	        error:
375	          `The registrar wouldn't cancel this transfer: ${errMsg(e)}. ` +
376	          `That usually means it has already gone through at the registry — refresh in a few minutes. ` +
377	          `Nothing has been credited or charged.`,
378	      };
379	    }
380	
381	    const refundCents = transferChargeCents(domain.priceCents);
382	    const settled = await settleFailedTransferIn({
383	      domainId: domain.id,
384	      transferStatus: "cancelled",
385	      reason: "Transfer cancelled at your request.",
386	    });
387	    await db.auditLog
388	      .create({ data: { userId: user.id, action: "domain.transfer_in.cancelled", detail: domain.name } })
389	      .catch(() => {});
390	    revalidatePath(`/dashboard/domains/${domainId}`);
391	    revalidatePath("/dashboard/domains");
392	
393	    return {
394	      note: settled
395	        ? `Transfer cancelled at the registrar and $${(refundCents / 100).toFixed(2)} credited back to your wallet.`
396	        : "This transfer had already been settled — no further credit was applied.",
397	    };
398	  } finally {
399	    endTransferSubmit(guardKey);
400	  }
401	}
