 * sweep, a racing customer-initiated cancel, and a worker restart therefore all
 * converge on exactly ONE credit. Returns true when this call was the one that
 * settled it.
 *
 * Only call this once the money is genuinely owed back — i.e. the registrar has
 * confirmed the transfer failed or was cancelled. Never on an unknown state.
 */
export async function settleFailedTransferIn(s: FailedTransferSettlement): Promise<boolean> {
  const domain = await db.domain.findUnique({ where: { id: s.domainId } });
  if (!domain || domain.status !== "TRANSFER_PENDING") return false;

  const refundCents = transferChargeCents(domain.priceCents);
  const description = transferChargeDescription(domain.name);

  return db.$transaction(async (tx) => {
    const swapped = await tx.domain.updateMany({
      where: { id: s.domainId, status: "TRANSFER_PENDING" },
      data: {
        status: "TRANSFER_FAILED",
        transferStatus: s.transferStatus,
        error: s.reason.slice(0, 500),
        // The customer's credential at their old registrar is no longer needed.
        transferAuthCodeEnc: null,
      },
    });
    if (swapped.count === 0) return false; // someone else already settled it

    if (refundCents > 0) {
      await tx.user.update({
        where: { id: domain.userId },
        data: { balanceCents: { increment: refundCents } },
      });
      await tx.walletTransaction.create({
        data: {
          userId: domain.userId,
          amountCents: refundCents,
          description: `Refund: transfer of ${domain.name} did not complete`,
        },
      });
      // Keep the ledger honest: the original PAID invoice becomes REFUNDED.
      // Matched on the exact description we stamped at charge time.
      await tx.invoice.updateMany({
        where: { userId: domain.userId, description, status: "PAID" },
        data: { status: "REFUNDED" },
      });
    }
    await tx.auditLog.create({
      data: {
        userId: domain.userId,
        action: "domain.transfer_in.refunded",
        detail: `${domain.name}: ${refundCents}c credited — ${s.reason}`.slice(0, 500),
      },
    });
    return true;
  });
}

/**
 * Mark an inbound transfer complete: the domain is ours to manage now. Scrubs
 * the stored auth code — we keep someone else's registrar credential no longer
 * than the transfer needs it. CAS-guarded, so it lands exactly once.
 */
export async function settleCompletedTransferIn(opts: {
  domainId: string;
  transferStatus: string;
  registeredAt: Date | null;
  expiresAt: Date;
}): Promise<boolean> {
  const res = await db.domain.updateMany({
    where: { id: opts.domainId, status: "TRANSFER_PENDING" },
    data: {
      status: "ACTIVE",
      transferStatus: opts.transferStatus,
      transferAuthCodeEnc: null,
      error: null,
      ...(opts.registeredAt ? { registeredAt: opts.registeredAt } : {}),
      expiresAt: opts.expiresAt,
    },
  });
  return res.count > 0;
}
